        # Pool order never changes when packages reserve units; sort only once.\n        sources = []\n        for target in range(n):\n            sources.append(sorted(\n                (delay + self.dist[node][target], node, i)\n                for i, (node, delay, count, movable) in enumerate(pools)\n            ))\n\n        arrivals = [[] for _ in range(n)]\n        for _, node, count, arrival in enemy_trips:\n            arrivals[node].append((arrival - turn, count))\n\n        base = self.bases[p]\n        enemy_base = self.bases[q]\n        leads = all_leads[p]\n        assigned = [False] * n\n        proposals = []\n        nearest_enemy = []\n        deployed = [u for u in range(n) if u != enemy_base and enemy[u] > 0]\n        for target in range(n):\n            nearest_enemy.append(min(\n                [self.dist[enemy_base][target] + 5] +\n                [self.dist[u][target] for u in deployed]\n            ))\n\n        for _package in range(n):\n            best_priority = 0.0\n            best_target = -1\n            best_selection = None\n            for target, value in enumerate(self.values):\n                if value <= 0 or assigned[target]:\n                    continue\n                ours = owners[target] == p\n                theirs = owners[target] == q\n                needed = 1\n                selection = None\n                opposing = 0\n                arrival_time = 0\n\n                for _iteration in range(6):\n                    missing = needed\n                    selected = []\n                    for travel, node, index in sources[target]:\n                        count = min(missing, pools[index][2])\n                        if count:\n                            selected.append((index, count, travel))\n                            missing -= count\n                        if missing == 0:\n                            break\n                    if missing:\n                        selection = None\n                  