_FALLBACK_SRC = '# Exact action format: list[tuple[int, int, int]], [(from_node, to_node, count), ...].\n# "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# "profit_p = revenue_p - upkeep_p"\n# Ownership persists without a garrison; capture requires two consecutive strict\n# majorities. This conservative strategy captures uncontested nodes and returns home.\n\nimport time\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_base):\n    """The specification\'s exact per-turn profit formula."""\n    revenue = sum(value for value, own in zip(values, owned) if own)\n    upkeep = UPKEEP * (UNITS_PER_PLAYER - units_at_base)\n    return float(revenue - upkeep)\n\n\ndef preprocess_map(obs):\n    n = int(obs["n_nodes"])\n    adjacency = [{} for _ in range(n)]\n    distance = [[10**6] * n for _ in range(n)]\n    hop = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n    for u, v, length in obs["edges"]:\n        adjacency[u][v] = length\n        adjacency[v][u] = length\n        distance[u][v] = distance[v][u] = length\n        hop[u][v], hop[v][u] = v, u\n    # Tiny fixed-size maps: Floyd-Warshall is simpler than a search framework.\n    for k in range(n):\n        for u in range(n):\n            for v in range(n):\n                candidate = distance[u][k] + distance[k][v]\n                if candidate < distance[u][v]:\n                    distance[u][v] = candidate\n                    hop[u][v] = hop[u][k]\n    return adjacency, distance, hop\n\n\ndef make_plan(obs, distance, hop, deadline):\n    n = int(obs["n_nodes"])\n    turn = int(obs["turn"])\n    remaining = N_TURNS - turn\n    base = int(obs["player_base"])\n    enemy_base = int(obs["opponent_base"])\n    units = obs["player_units"]\n    enemy = obs["opponent_units"]\n    values = obs["node_value"]\n    owned = obs["player_owned"]\n    leads = obs["player_lead_turns"]\n\n    # Each agent is (current/landing node, turns until movable, on-node flag).\n    # Transit agents reserve work too, so another unit is not sent after them.\n    agents = []\n    for node, count in enumerate(units):\n        for _ in range(count):\n            agents.append((node, 0, True))\n    for _, destination, count, arrival in obs.get("player_transits", []):\n        for _ in range(count):\n            agents.append((destination, max(0, arrival - turn), False))\n\n    threats = [(v, 0) for v in range(n) if enemy[v] and v != enemy_base]\n    incoming_enemy = [0] * n\n    for _, destination, count, arrival in obs.get("opponent_transits", []):\n        incoming_enemy[destination] += count\n        threats.append((destination, max(0, arrival - turn)))\n\n    targets = [\n        v for v in range(n)\n        if v != base and v != enemy_base and values[v] > 0\n        and not owned[v] and enemy[v] == 0 and incoming_enemy[v] == 0\n    ]\n\n    candidates = []\n    for index, (source, delay, on_node) in enumerate(agents):\n        for target in targets:\n            travel = delay + distance[source][target]\n            # An existing lead needs just one further end-of-turn check.\n            if source == target and delay == 0:\n                capture_offset = 0 if leads[target] >= 1 else 1\n            elif source == target:\n                capture_offset = delay\n            else:\n                capture_offset = travel\n            earning_turns = remaining - capture_offset\n            if earning_turns <= 0:\n                continue\n\n            # Avoid fights, rather than paying for extra units to contest them.\n            if any(wait + distance[position][target] <= travel + 2\n                   for position, wait in threats):\n                continue\n\n            # Conservative full trip budget, including a capture wait and\n            # return home. Already-paid travel is sunk, not counted as revenue.\n            away_budget = travel + 2 + distance[target][base]\n            cost = UPKEEP * away_budget\n            revenue = values[target] * earning_turns\n            # Require a clear surplus, not merely theoretical break-even.\n            if revenue <= cost + max(6.0, 0.15 * cost):\n                continue\n            candidates.append((travel, -values[target], target, index))\n\n    candidates.sort()\n    assigned_agents = set()\n    assigned_targets = set()\n    destinations = {}\n    for _, _, target, index in candidates:\n        if time.perf_counter() >= deadline:\n            break\n        if index in assigned_agents or target in assigned_targets:\n            continue\n        assigned_agents.add(index)\n        assigned_targets.add(target)\n        destinations[index] = target\n\n    plan = {}\n    for index, (source, _, on_node) in enumerate(agents):\n        if not on_node:\n            continue\n        target = destinations.get(index, base)\n        if source == target:\n            continue\n        next_node = hop[source][target]\n        if next_node >= 0:\n            key = (source, next_node)\n            plan[key] = plan.get(key, 0) + 1\n    return plan\n\n\ndef legal_action(plan, obs, adjacency):\n    """Replay against start-of-turn availability; never reuse arriving units."""\n    available = list(obs["player_units"])\n    n = len(available)\n    action = []\n    for (source, destination), requested in sorted(plan.items()):\n        source, destination = int(source), int(destination)\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if destination not in adjacency[source]:\n            continue\n        count = int(min(max(0, requested), available[source]))\n        if count > 0:\n            action.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_cache = None\n        self.bad_reports = 0\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        if not obs.get("player_units"):\n            return []\n        if self.map_cache is None:\n            self.map_cache = preprocess_map(obs)\n        adjacency, distance, hop = self.map_cache\n\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n\n        if self.bad_reports >= 2:\n            # Conservative permanent fallback: only return units home.\n            base = int(obs["player_base"])\n            plan = {}\n            for source, count in enumerate(obs["player_units"]):\n                destination = hop[source][base]\n                if source != base and count > 0 and destination >= 0:\n                    plan[(source, destination)] = int(count)\n        else:\n            plan = make_plan(obs, distance, hop, deadline)\n        return legal_action(plan, obs, adjacency)\n'
